import React from 'react';
import ReactgDOM from 'react-dom/client';
import App from './App';
import './index.scss';
import {BrowserRouter} from "react-router-dom";

const root = ReactgDOM.createRoot(document.getElementById('root'));
root.render(
    <BrowserRouter>
        <App />
    </BrowserRouter>
);

export default root;
